import 'app_language.dart';

const mistakeBankKeys = [
  'title',
  'hint',
  'skip',
  'instructions',
  'replying',
  'wrong',
  'unavailable',
  'saveError',
  'piecePrompt',
  'P',
  'N',
  'B',
  'R',
  'Q',
  'K',
];

final mistakeBankTranslations = {
  for (final entry in _rows.entries) entry.key: entry.value.split('|'),
};

String mistakeBankText(
  String key,
  String language, [
  Map<String, String> values = const {},
]) {
  final index = mistakeBankKeys.indexOf(key);
  if (index < 0) throw ArgumentError.value(key, 'key');
  var result =
      mistakeBankTranslations[AppLanguageController.resolveCode(
        language,
      )]![index];
  for (final entry in values.entries) {
    result = result.replaceAll('{${entry.key}}', entry.value);
  }
  return result;
}

